    private static final class TestResourceItem implements ITestResourceItem {

        private final String name;
        private final String contents;
        private int readCount;

        private TestResourceItem(final String name, final String contents) {
            this.name = name;
            this.contents = contents;
        }

        @Override
        public String getName() {
            return this.name;
        }

        @Override
        public String readAsText() {
            this.readCount++;
            return this.contents;
        }

        private int getReadCount() {
            return this.readCount;
        }

    }


    private static final class TestResourceContainer implements ITestResourceContainer {

        private final String name;
        private final List<ITestResource> containedResources;

        private TestResourceContainer(final String name, final ITestResource... containedResources) {
            this(name, Arrays.asList(containedResources));
        }

        private TestResourceContainer(final String name, final List<ITestResource> containedResources) {
            this.name = name;
            this.containedResources = containedResources;
        }

        @Override
        public String getName() {
            return this.name;
        }

        @Override
        public List<ITestResource> getContainedResources() {
            return this.containedResources;
        }

    }


    private static final class RecordingResourceResolver implements ITestResourceResolver {

        private final Map<String, ITestResource> resources = new HashMap<String, ITestResource>();
        private final List<String> requestedNames = new ArrayList<String>();
        private final List<ITestResource> relativeResources = new ArrayList<ITestResource>();

        private void put(final String name, final ITestResource resource) {
            this.resources.put(name, resource);
        }

        @Override
        public ITestResource resolve(final String resourceName) {
            this.requestedNames.add(resourceName);
            return this.resources.get(resourceName);
        }

        @Override
        public ITestResource resolve(final String resourceName, final ITestResource relativeTo) {
            this.requestedNames.add(resourceName);
            this.relativeResources.add(relativeTo);
            return this.resources.get(resourceName);
        }

        private List<String> getRequestedNames() {
            return this.requestedNames;
        }

        private List<ITestResource> getRelativeResources() {
            return this.relativeResources;
        }

    }


    private static final class TrackingResolver extends StandardTestableResolver {

        private final List<String> computedTestItems = new ArrayList<String>();

        @Override
        protected TestableType computeTestableType(final ITestResource resource) {
            if (resource instanceof ITestResourceItem &&
                    resource.getName() != null &&
                    resource.getName().toUpperCase().endsWith(".THTEST")) {
                this.computedTestItems.add(resource.getName());
                return TestableType.SEQUENCE;
            }
            return super.computeTestableType(resource);
        }


        @Override
        protected ITestSequence resolveAsTestSequence(
                final String executionId, final ITestResource resource) {
            if (resource instanceof ITestResourceItem) {
                final TestSequence testSequence = new TestSequence();
                testSequence.setName("resolved:" + resource.getName());
                return testSequence;
            }
            return super.resolveAsTestSequence(executionId, resource);
        }

    }

}

