    @Test
    public void testBeansAreAlsoLookedUpInParentApplicationContexts() {

        final GenericApplicationContext parentContext = new GenericApplicationContext();
        parentContext.getBeanFactory().registerSingleton(ACL_SERVICE_BEAN_NAME, this.aclService);
        parentContext.refresh();

        final GenericWebApplicationContext childContext = newApplicationContext(parentContext);
        final IExpressionContext childExpressionContext = newExpressionContext(childContext);

        registerCustomRetrievalStrategiesIn(parentContext);

        when(this.aclService.readAclById(this.objectIdentity, this.sids)).thenReturn(this.acl);
        when(this.acl.isGranted(this.permissions, this.sids, false)).thenReturn(true);

        final boolean result = AclAuthUtils.authorizeUsingAccessControlList(
                childExpressionContext, this.domainObject, this.permissions, this.authentication);

        assertTrue(result, "Beans registered in a parent application context must be visible");
        verify(this.sidRetrievalStrategy).getSids(this.authentication);
        verify(this.objectIdentityRetrievalStrategy).getObjectIdentity(this.domainObject);

    }




    // ---------------------------------------------------------------------
    // Helpers
