    private void registerCustomRetrievalStrategies() {
        registerCustomRetrievalStrategiesIn(this.applicationContext);
    }

    private void registerCustomRetrievalStrategiesIn(final GenericApplicationContext targetContext) {
        targetContext.getBeanFactory().registerSingleton(
                SID_RETRIEVAL_STRATEGY_BEAN_NAME, this.sidRetrievalStrategy);
        targetContext.getBeanFactory().registerSingleton(
                OBJECT_IDENTITY_RETRIEVAL_STRATEGY_BEAN_NAME, this.objectIdentityRetrievalStrategy);
        when(this.sidRetrievalStrategy.getSids(this.authentication)).thenReturn(this.sids);
        when(this.objectIdentityRetrievalStrategy.getObjectIdentity(this.domainObject)).thenReturn(this.objectIdentity);
    }

    private static GenericWebApplicationContext newApplicationContext(final ApplicationContext parent) {
        final GenericWebApplicationContext newContext = new GenericWebApplicationContext();
        if (parent != null) {
            newContext.setParent(parent);
        }
        newContext.refresh();
        return newContext;
    }

    private static void registerBean(
            final GenericWebApplicationContext targetContext, final String name, final Object bean) {
        targetContext.getBeanFactory().registerSingleton(name, bean);
    }

    private static IExpressionContext newExpressionContext(final WebApplicationContext webApplicationContext) {

        final ServletContext servletContext = mock(ServletContext.class);
        when(servletContext.getAttribute(WebApplicationContext.ROOT_WEB_APPLICATION_CONTEXT_ATTRIBUTE))
                .thenReturn(webApplicationContext);

        final IServletWebApplication servletWebApplication = mock(IServletWebApplication.class);
        when(servletWebApplication.getNativeServletContextObject()).thenReturn(servletContext);

        final IServletWebExchange servletWebExchange = mock(IServletWebExchange.class);
        when(servletWebExchange.getApplication()).thenReturn(servletWebApplication);

        final IExpressionContext expressionContext =
                mock(IExpressionContext.class, Mockito.withSettings().extraInterfaces(IWebContext.class));
        when(((IWebContext) expressionContext).getExchange()).thenReturn(servletWebExchange);

        return expressionContext;

    }

    @SuppressWarnings("unchecked")
    private static ArgumentCaptor<List<Permission>> newPermissionListCaptor() {
        return (ArgumentCaptor<List<Permission>>) (ArgumentCaptor<?>) ArgumentCaptor.forClass(List.class);
    }

    @SuppressWarnings("unchecked")
    private static ArgumentCaptor<List<Sid>> newSidListCaptor() {
        return (ArgumentCaptor<List<Sid>>) (ArgumentCaptor<?>) ArgumentCaptor.forClass(List.class);
    }

    private static ArgumentCaptor<ObjectIdentity> newObjectIdentityCaptor() {
        return ArgumentCaptor.forClass(ObjectIdentity.class);
    }




