    private void stubTagAttributes(final Map<String, String> tagAttributes) {

        when(this.tag.getAttributeValue(any(AttributeName.class))).thenAnswer(invocation -> {
            final AttributeName attributeName = invocation.getArgument(0);
            return tagAttributes.get(attributeName.getAttributeName());
        });
        when(this.tag.hasAttribute(any(AttributeName.class))).thenAnswer(invocation -> {
            final AttributeName attributeName = invocation.getArgument(0);
            return Boolean.valueOf(tagAttributes.containsKey(attributeName.getAttributeName()));
        });

    }


    private static Map<String, String> attributes(final String... pairs) {

        if (pairs.length % 2 != 0) {
            throw new IllegalArgumentException("An even number of arguments is required");
        }
        final Map<String, String> result = new LinkedHashMap<String, String>(pairs.length / 2, 1.0f);
        for (int i = 0; i < pairs.length; i += 2) {
            result.put(pairs[i], pairs[i + 1]);
        }
        return result;

    }


    @SuppressWarnings("unchecked")
    private static ArgumentCaptor<Map<String, String>> mapCaptor() {
        return (ArgumentCaptor<Map<String, String>>) (ArgumentCaptor<?>) ArgumentCaptor.forClass(Map.class);
    }


