        private final HttpHeaders headers = new HttpHeaders();
        private final DataBufferFactory bufferFactory = new DefaultDataBufferFactory();
        private final MultiValueMap<String, ResponseCookie> cookies = new LinkedMultiValueMap<>();

        private String writeMode;
        private String body;

        @Override
        public HttpHeaders getHeaders() {
            return this.headers;
        }

        @Override
        public DataBufferFactory bufferFactory() {
            return this.bufferFactory;
        }

        @Override
        public boolean setStatusCode(final HttpStatus status) {
            return true;
        }

        @Override
        public HttpStatus getStatusCode() {
            return null;
        }

        @Override
        public MultiValueMap<String, ResponseCookie> getCookies() {
            return this.cookies;
        }

        @Override
        public void addCookie(final ResponseCookie cookie) {
            this.cookies.add(cookie.getName(), cookie);
        }

        @Override
        public void beforeCommit(final Supplier<? extends Mono<Void>> action) {
            // no-op
        }

        @Override
        public boolean isCommitted() {
            return false;
        }

        @Override
        public Mono<Void> setComplete() {
            return Mono.empty();
        }

        @Override
        public Mono<Void> writeWith(final Publisher<? extends DataBuffer> body) {
            this.writeMode = "writeWith";
            this.body = readBuffers(body);
            return Mono.empty();
        }

        @Override
        public Mono<Void> writeAndFlushWith(
                final Publisher<? extends Publisher<? extends DataBuffer>> body) {
            this.writeMode = "writeAndFlushWith";
            this.body = readBuffers(Flux.from(body).flatMap(inner -> Flux.from(inner)));
            return Mono.empty();
        }
    }


    private static final class RecordingTemplateEngine extends SpringWebFluxTemplateEngine {

        private final String output;

        private int invocations;
        private String template;
        private Set<String> markupSelectors;
        private IContext context;
        private MediaType mediaType;
        private Charset charset;
        private int maxChunkSizeBytes;

        private RecordingTemplateEngine(final String output) {
            this.output = output;
        }

        @Override
        public Publisher<DataBuffer> processStream(
                final String template, final Set<String> markupSelectors, final IContext context,
                final DataBufferFactory bufferFactory, final MediaType mediaType, final Charset charset) {
            return processStream(template, markupSelectors, context, bufferFactory, mediaType, charset,
                    Integer.MAX_VALUE);
        }

        @Override
        public Publisher<DataBuffer> processStream(
                final String template, final Set<String> markupSelectors, final IContext context,
                final DataBufferFactory bufferFactory, final MediaType mediaType, final Charset charset,
                final int responseMaxChunkSizeBytes) {
            this.invocations++;
            this.template = template;
            this.markupSelectors = markupSelectors;
            this.context = context;
            this.mediaType = mediaType;
            this.charset = charset;
            this.maxChunkSizeBytes = responseMaxChunkSizeBytes;
            return Flux.just(bufferFactory.wrap(this.output.getBytes(charset)));
        }
    }
}

