    private static IEngineConfiguration engineConfiguration(
            final ICacheManager cacheManager,
            final Set<ITemplateResolver> templateResolvers,
            final Set<IMessageResolver> messageResolvers,
            final Set<ILinkBuilder> linkBuilders,
            final Set<DialectConfiguration> dialectConfigurations) {

        return newProxy(
                IEngineConfiguration.class,
                "getCacheManager", cacheManager,
                "getTemplateResolvers", templateResolvers,
                "getMessageResolvers", messageResolvers,
                "getLinkBuilders", linkBuilders,
                "getDialectConfigurations", dialectConfigurations);

    }


    private static String expectedMessage(
            final String cacheManagerDescription,
            final List<String> templateResolverLines,
            final List<String> messageResolverLines,
            final List<String> linkBuilderLines,
            final List<String> dialectLines) {

        final List<String> lines = new ArrayList<String>();
        lines.add("Initializing Thymeleaf Template engine configuration...");
        lines.add("[THYMELEAF] TEMPLATE ENGINE CONFIGURATION:");
        final String versionLine = versionLine();
        if (versionLine != null) {
            lines.add(versionLine);
        }
        lines.add("[THYMELEAF] * Cache Manager implementation: " + cacheManagerDescription);
        lines.add("[THYMELEAF] * Template resolvers:");
        lines.addAll(templateResolverLines);
        lines.add("[THYMELEAF] * Message resolvers:");
        lines.addAll(messageResolverLines);
        lines.add("[THYMELEAF] * Link builders:");
        lines.addAll(linkBuilderLines);
        lines.addAll(dialectLines);
        lines.add("[THYMELEAF] TEMPLATE ENGINE CONFIGURED OK");
        return String.join("\n", lines);

    }


    private static String versionLine() {
        final String version = Thymeleaf.getVersion();
        final String buildTimestamp = Thymeleaf.getBuildTimestamp();
        if (isEmptyOrWhitespace(version)) {
            return null;
        }
        final String line = "[THYMELEAF] * Thymeleaf version: " + version;
        if (isEmptyOrWhitespace(buildTimestamp)) {
            return line;
        }
        return line + " (built " + buildTimestamp + ")";
    }


    private static boolean isEmptyOrWhitespace(final String value) {
        return value == null || value.trim().isEmpty();
    }


    private static String loggedClassName(final Class<?> clazz) {
        // ConfigLogBuilder replaces "$" with "." in every logged parameter.
        return clazz.getName().replace('$', '.');
    }


    private static String resolverLine(final Integer order, final String name) {
        if (order == null) {
            return "[THYMELEAF]     * " + name;
        }
        return "[THYMELEAF]     * [" + order + "] " + name;
    }


    private static String singleDialectLine(final IDialect dialect) {
        return "[THYMELEAF] * Dialect: " + dialect.getName() + " (" + loggedClassName(dialect.getClass()) + ")";
    }


    private static String indexedDialectLine(final int index, final int total, final IDialect dialect) {
        return "[THYMELEAF] * Dialect [" + index + " of " + total + "]: "
                + dialect.getName() + " (" + loggedClassName(dialect.getClass()) + ")";
    }


    private static String prefixLine(final String prefix) {
        return "[THYMELEAF]     * Prefix: \"" + (prefix == null ? "(none)" : prefix) + "\"";
    }


    @SafeVarargs
    private static <T> Set<T> linkedSet(final T... values) {
        final Set<T> set = new LinkedHashSet<T>();
        Collections.addAll(set, values);
        return set;
    }


    @SuppressWarnings("unchecked")
    private static <T> T newProxy(final Class<T> iface, final Object... nameValuePairs) {

        final Map<String, Object> answers = new HashMap<String, Object>();
        for (int i = 0; i < nameValuePairs.length; i += 2) {
            answers.put((String) nameValuePairs[i], nameValuePairs[i + 1]);
        }

        final InvocationHandler handler = new InvocationHandler() {
            @Override
            public Object invoke(final Object proxy, final Method method, final Object[] args) throws Throwable {
                final String methodName = method.getName();
                if ("toString".equals(methodName)) {
                    return iface.getSimpleName() + "Stub";
                }
                if ("hashCode".equals(methodName)) {
                    return Integer.valueOf(System.identityHashCode(proxy));
                }
                if ("equals".equals(methodName)) {
                    return Boolean.valueOf(proxy == args[0]);
                }
                if (answers.containsKey(methodName)) {
                    return answers.get(methodName);
                }
                final Class<?> returnType = method.getReturnType();
                if (returnType == boolean.class) {
                    return Boolean.FALSE;
                }
                if (returnType == int.class) {
                    return Integer.valueOf(0);
                }
                if (returnType == long.class) {
                    return Long.valueOf(0L);
                }
                if (returnType == double.class) {
                    return Double.valueOf(0.0d);
                }
                if (returnType == float.class) {
                    return Float.valueOf(0.0f);
                }
                if (returnType == short.class) {
                    return Short.valueOf((short) 0);
                }
                if (returnType == byte.class) {
                    return Byte.valueOf((byte) 0);
                }
                if (returnType == char.class) {
                    return Character.valueOf('\0');
                }
                return null;
            }
        };

        return iface.cast(Proxy.newProxyInstance(iface.getClassLoader(), new Class<?>[] {iface}, handler));

    }


    private static final class PlainDialect implements IDialect {

        private final String name;

        private PlainDialect(final String name) {
            this.name = name;
        }

        @Override
        public String getName() {
            return this.name;
        }

    }


    private static final class ProcessorDialect implements IProcessorDialect {

        private final String name;
        private final String prefix;
        private final Set<IProcessor> processors;

        private ProcessorDialect(final String name, final String prefix) {
            this(name, prefix, Collections.<IProcessor>emptySet());
        }

        private ProcessorDialect(final String name, final String prefix, final Set<IProcessor> processors) {
            this.name = name;
            this.prefix = prefix;
            this.processors = processors;
        }

        @Override
        public String getName() {
            return this.name;
        }

        @Override
        public String getPrefix() {
            return this.prefix;
        }

        @Override
        public int getDialectProcessorPrecedence() {
            return 0;
        }

        @Override
        public Set<IProcessor> getProcessors(final String dialectPrefix) {
            return this.processors;
        }

    }

