    @Test
    public void testAllProcessorTypesAreRegisteredUnderTheirTemplateMode() {

        final TestElementTagProcessor elementProcessor = new TestElementTagProcessor(TemplateMode.HTML, "dialectPrefix", "div", 100);
        final TestTemplateBoundariesProcessor templateBoundariesProcessor = new TestTemplateBoundariesProcessor(TemplateMode.HTML, 110);
        final TestCDATASectionProcessor cdataSectionProcessor = new TestCDATASectionProcessor(TemplateMode.HTML, 120);
        final TestCommentProcessor commentProcessor = new TestCommentProcessor(TemplateMode.HTML, 130);
        final TestDocTypeProcessor docTypeProcessor = new TestDocTypeProcessor(TemplateMode.HTML, 140);
        final TestProcessingInstructionProcessor processingInstructionProcessor = new TestProcessingInstructionProcessor(TemplateMode.HTML, 150);
        final TestTextProcessor textProcessor = new TestTextProcessor(TemplateMode.HTML, 160);
        final TestXMLDeclarationProcessor xmlDeclarationProcessor = new TestXMLDeclarationProcessor(TemplateMode.HTML, 170);

        final TestProcessorDialect dialect = new TestProcessorDialect(
                "dialectPrefix", 0,
                processors(
                        elementProcessor, templateBoundariesProcessor, cdataSectionProcessor, commentProcessor,
                        docTypeProcessor, processingInstructionProcessor, textProcessor, xmlDeclarationProcessor));

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        assertEquals(1, configuration.getElementProcessors(TemplateMode.HTML).size());
        assertSame(
                elementProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getElementProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).size());
        assertSame(
                templateBoundariesProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getCDATASectionProcessors(TemplateMode.HTML).size());
        assertSame(
                cdataSectionProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getCDATASectionProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getCommentProcessors(TemplateMode.HTML).size());
        assertSame(
                commentProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getCommentProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getDocTypeProcessors(TemplateMode.HTML).size());
        assertSame(
                docTypeProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getDocTypeProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getProcessingInstructionProcessors(TemplateMode.HTML).size());
        assertSame(
                processingInstructionProcessor,
                ProcessorConfigurationUtils.unwrap(
                        configuration.getProcessingInstructionProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getTextProcessors(TemplateMode.HTML).size());
        assertSame(
                textProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getTextProcessors(TemplateMode.HTML).iterator().next()));

        assertEquals(1, configuration.getXMLDeclarationProcessors(TemplateMode.HTML).size());
        assertSame(
                xmlDeclarationProcessor,
                ProcessorConfigurationUtils.unwrap(configuration.getXMLDeclarationProcessors(TemplateMode.HTML).iterator().next()));

        for (final TemplateMode templateMode : Arrays.asList(
                TemplateMode.XML, TemplateMode.TEXT, TemplateMode.JAVASCRIPT, TemplateMode.CSS)) {
            assertTrue(configuration.getElementProcessors(templateMode).isEmpty());
            assertTrue(configuration.getTemplateBoundariesProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCDATASectionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getCommentProcessors(templateMode).isEmpty());
            assertTrue(configuration.getDocTypeProcessors(templateMode).isEmpty());
            assertTrue(configuration.getProcessingInstructionProcessors(templateMode).isEmpty());
            assertTrue(configuration.getTextProcessors(templateMode).isEmpty());
            assertTrue(configuration.getXMLDeclarationProcessors(templateMode).isEmpty());
        }

    }


    @Test
    public void testProcessorsAreGroupedByTemplateMode() {

        final TestTextProcessor htmlProcessor = new TestTextProcessor(TemplateMode.HTML, 10);
        final TestTextProcessor textProcessor = new TestTextProcessor(TemplateMode.TEXT, 20);
        final TestTextProcessor xmlProcessor = new TestTextProcessor(TemplateMode.XML, 30);

        final TestProcessorDialect dialect = new TestProcessorDialect(
                "dialectPrefix", 0, processors(htmlProcessor, textProcessor, xmlProcessor));

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        assertEquals(Collections.singletonList(htmlProcessor), unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.HTML)));
        assertEquals(Collections.singletonList(textProcessor), unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.TEXT)));
        assertEquals(Collections.singletonList(xmlProcessor), unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.XML)));
        assertTrue(configuration.getTextProcessors(TemplateMode.JAVASCRIPT).isEmpty());
        assertTrue(configuration.getTextProcessors(TemplateMode.CSS).isEmpty());

    }


    @Test
    public void testProcessorsAreSortedByPrecedence() {

        final TestTextProcessor precedence30 = new TestTextProcessor(TemplateMode.HTML, 30);
        final TestTextProcessor precedence10 = new TestTextProcessor(TemplateMode.HTML, 10);
        final TestTextProcessor precedence20 = new TestTextProcessor(TemplateMode.HTML, 20);

        // Deliberately unsorted insertion order
        final TestProcessorDialect dialect = new TestProcessorDialect(
                "dialectPrefix", 0, processors(precedence30, precedence10, precedence20));

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        assertEquals(
                Arrays.asList(precedence10, precedence20, precedence30),
                unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.HTML)));

    }


    @Test
    public void testDialectPrecedenceIsAppliedBeforeProcessorPrecedence() {

        final TestTextProcessor processorOfLowDialectPrecedence = new TestTextProcessor(TemplateMode.HTML, 100);
        final TestTextProcessor processorOfHighDialectPrecedence = new TestTextProcessor(TemplateMode.HTML, 0);

        final TestProcessorDialect lowDialectPrecedence =
                new TestProcessorDialect("low", 5, processors(processorOfLowDialectPrecedence));
        final TestProcessorDialect highDialectPrecedence =
                new TestProcessorDialect("high", 20, processors(processorOfHighDialectPrecedence));

        // The dialect with the highest dialect precedence is added first, so insertion order is not the expected one
        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(highDialectPrecedence),
                new DialectConfiguration(lowDialectPrecedence)));

        assertEquals(
                Arrays.asList(processorOfLowDialectPrecedence, processorOfHighDialectPrecedence),
                unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.HTML)));

    }


    @Test
    public void testProcessorsOfSeveralDialectsAreMerged() {

        final TestCommentProcessor firstProcessor = new TestCommentProcessor(TemplateMode.HTML, 50);
        final TestCommentProcessor secondProcessor = new TestCommentProcessor(TemplateMode.HTML, 10);

        final TestProcessorDialect firstDialect = new TestProcessorDialect("first", 0, processors(firstProcessor));
        final TestProcessorDialect secondDialect = new TestProcessorDialect("second", 0, processors(secondProcessor));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(firstDialect), new DialectConfiguration(secondDialect)));

        assertEquals(2, configuration.getDialects().size());
        assertTrue(configuration.getDialects().contains(firstDialect));
        assertTrue(configuration.getDialects().contains(secondDialect));
        assertEquals(
                Arrays.asList(secondProcessor, firstProcessor),
                unwrapCommentProcessors(configuration.getCommentProcessors(TemplateMode.HTML)));

    }


