    @Test
    public void testStandardDialectReportedWithItsDefaultPrefix() {

        final StandardDialect standardDialect = new StandardDialect();

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(standardDialect)));

        assertTrue(configuration.isStandardDialectPresent());
        assertEquals("th", configuration.getStandardDialectPrefix());
        assertEquals(Collections.singleton(standardDialect), configuration.getDialects());

        assertFalse(configuration.getElementProcessors(TemplateMode.HTML).isEmpty());
        assertFalse(configuration.getTextProcessors(TemplateMode.HTML).isEmpty());
        assertFalse(configuration.getCDATASectionProcessors(TemplateMode.HTML).isEmpty());
        assertFalse(configuration.getCommentProcessors(TemplateMode.HTML).isEmpty());
        assertFalse(configuration.getTemplateBoundariesProcessors(TemplateMode.HTML).isEmpty());
        assertFalse(configuration.getElementProcessors(TemplateMode.CSS).isEmpty());
        assertTrue(configuration.getXMLDeclarationProcessors(TemplateMode.HTML).isEmpty());
        assertTrue(configuration.getXMLDeclarationProcessors(TemplateMode.CSS).isEmpty());

        assertEquals(5, configuration.getExecutionAttributes().size());
        assertTrue(configuration.hasExecutionAttribute(
                StandardExpressions.STANDARD_VARIABLE_EXPRESSION_EVALUATOR_ATTRIBUTE_NAME));
        assertSame(
                standardDialect.getVariableExpressionEvaluator(),
                configuration.getExecutionAttribute(
                        StandardExpressions.STANDARD_VARIABLE_EXPRESSION_EVALUATOR_ATTRIBUTE_NAME));

        final Set<String> expressionObjectNames =
                configuration.getExpressionObjectFactory().getAllExpressionObjectNames();
        assertNotNull(expressionObjectNames);
        assertTrue(expressionObjectNames.contains("ctx"));
        assertTrue(expressionObjectNames.contains("conversions"));

    }


