    @Test
    public void testStandardDialectIsMergedWithOtherDialects() {

        final StandardDialect standardDialect = new StandardDialect();
        final TestTextProcessor textProcessor = new TestTextProcessor(TemplateMode.HTML, 0);
        final TestProcessorDialect dialect = new TestProcessorDialect("dialectPrefix", 0, processors(textProcessor));

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(standardDialect), new DialectConfiguration(dialect)));

        assertTrue(configuration.isStandardDialectPresent());
        assertEquals("th", configuration.getStandardDialectPrefix());
        assertEquals(2, configuration.getDialects().size());
        assertTrue(configuration.getDialects().contains(standardDialect));
        assertTrue(configuration.getDialects().contains(dialect));

        final List<ITextProcessor> textProcessors = unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.HTML));
        assertTrue(textProcessors.size() > 1);
        // The standard dialect has a very high dialect precedence (1000), so our processor must come first
        assertSame(textProcessor, textProcessors.get(0));

    }

