    @Test
    public void testExecutionAttributesOfAllDialectsAreMerged() {

        final Map<String, Object> firstAttributes = new LinkedHashMap<String, Object>();
        firstAttributes.put("firstAttribute", "firstValue");
        firstAttributes.put("secondAttribute", Integer.valueOf(23));

        final Map<String, Object> secondAttributes = new LinkedHashMap<String, Object>();
        secondAttributes.put("thirdAttribute", Boolean.TRUE);

        final TestExecutionAttributeDialect firstDialect = new TestExecutionAttributeDialect("first", firstAttributes);
        final TestExecutionAttributeDialect secondDialect = new TestExecutionAttributeDialect("second", secondAttributes);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(firstDialect), new DialectConfiguration(secondDialect)));

        assertEquals(3, configuration.getExecutionAttributes().size());
        assertEquals(
                Arrays.asList("firstAttribute", "secondAttribute", "thirdAttribute"),
                new ArrayList<String>(configuration.getExecutionAttributes().keySet()));

        assertTrue(configuration.hasExecutionAttribute("firstAttribute"));
        assertEquals("firstValue", configuration.getExecutionAttribute("firstAttribute"));
        assertTrue(configuration.hasExecutionAttribute("secondAttribute"));
        assertEquals(Integer.valueOf(23), configuration.getExecutionAttribute("secondAttribute"));
        assertTrue(configuration.hasExecutionAttribute("thirdAttribute"));
        assertEquals(Boolean.TRUE, configuration.getExecutionAttribute("thirdAttribute"));
        assertFalse(configuration.hasExecutionAttribute("nonExistentAttribute"));
        assertNull(configuration.getExecutionAttribute("nonExistentAttribute"));

    }


