    @Test
    public void testConflictingExecutionAttributesCauseConfigurationException() {

        final Map<String, Object> firstAttributes = new LinkedHashMap<String, Object>();
        firstAttributes.put("conflictingAttribute", "firstValue");

        final Map<String, Object> secondAttributes = new LinkedHashMap<String, Object>();
        secondAttributes.put("conflictingAttribute", "secondValue");

        final TestExecutionAttributeDialect firstDialect = new TestExecutionAttributeDialect("first", firstAttributes);
        final TestExecutionAttributeDialect secondDialect = new TestExecutionAttributeDialect("second", secondAttributes);

        final ConfigurationException exception = assertThrows(
                ConfigurationException.class,
                () -> DialectSetConfiguration.build(configurations(
