    @Test
    public void testExpressionObjectFactoriesOfAllDialectsAreAggregated() {

        final TestExpressionObjectFactory firstFactory = new TestExpressionObjectFactory(
                new LinkedHashSet<String>(Arrays.asList("firstObject", "secondObject")), true);
        final TestExpressionObjectFactory secondFactory = new TestExpressionObjectFactory(
                new LinkedHashSet<String>(Collections.singletonList("thirdObject")), false);

        final DialectSetConfiguration configuration = DialectSetConfiguration.build(configurations(
                new DialectConfiguration(new TestExpressionObjectDialect("first", firstFactory)),
                new DialectConfiguration(new TestExpressionObjectDialect("second", secondFactory))));

        final IExpressionObjectFactory aggregatedFactory = configuration.getExpressionObjectFactory();

        final Set<String> names = aggregatedFactory.getAllExpressionObjectNames();
        assertNotNull(names);
        assertEquals(3, names.size());
        assertTrue(names.contains("firstObject"));
        assertTrue(names.contains("secondObject"));
        assertTrue(names.contains("thirdObject"));
        assertFalse(names.contains("nonExistentObject"));

        assertEquals("firstObjectObject", aggregatedFactory.buildObject(null, "firstObject"));
        assertEquals("thirdObjectObject", aggregatedFactory.buildObject(null, "thirdObject"));
        assertNull(aggregatedFactory.buildObject(null, "nonExistentObject"));

        assertTrue(aggregatedFactory.isCacheable("firstObject"));
        assertFalse(aggregatedFactory.isCacheable("thirdObject"));
        assertFalse(aggregatedFactory.isCacheable("nonExistentObject"));

    }


