                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        // The definition objects must be fully usable after the build operation (they are not just placeholders)
        final HTMLElementDefinition divDefinition = configuration.getElementDefinitions().forHTMLName("div");
        assertNotNull(divDefinition);
        assertTrue(divDefinition.hasAssociatedProcessors());
