    @Test
    public void testElementProcessorsAreSortedByPrecedenceAndDefinitionsKeepThatOrder() {

        final TestElementTagProcessor precedence30 = new TestElementTagProcessor(TemplateMode.HTML, "dialectPrefix", "div", 30);
        final TestElementTagProcessor precedence10 = new TestElementTagProcessor(TemplateMode.HTML, "dialectPrefix", "div", 10);
        final TestElementTagProcessor precedence20 = new TestElementTagProcessor(TemplateMode.HTML, "dialectPrefix", "div", 20);

        final TestProcessorDialect dialect = new TestProcessorDialect(
                "dialectPrefix", 0, processors(precedence30, precedence10, precedence20));

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        final List<IElementProcessor> elementProcessors = new ArrayList<IElementProcessor>();
        for (final IElementProcessor processor : configuration.getElementProcessors(TemplateMode.HTML)) {
            elementProcessors.add(ProcessorConfigurationUtils.unwrap(processor));
        }
        assertEquals(Arrays.asList(precedence10, precedence20, precedence30), elementProcessors);

        final List<IElementProcessor> definitionProcessors = new ArrayList<IElementProcessor>();
        for (final IElementProcessor processor :
                configuration.getElementDefinitions().forHTMLName("div").getAssociatedProcessors()) {
            definitionProcessors.add(ProcessorConfigurationUtils.unwrap(processor));
        }
        assertEquals(Arrays.asList(precedence10, precedence20, precedence30), definitionProcessors);

    }


