    private static Set<DialectConfiguration> configurations(final DialectConfiguration... dialectConfigurations) {
        final Set<DialectConfiguration> configurations = new LinkedHashSet<DialectConfiguration>();
        Collections.addAll(configurations, dialectConfigurations);
        return configurations;
