    private static Set<IProcessor> processors(final IProcessor... processors) {
        final Set<IProcessor> processorSet = new LinkedHashSet<IProcessor>();
        Collections.addAll(processorSet, processors);
        return processorSet;
    }


    private static List<ITextProcessor> unwrapTextProcessors(final Set<ITextProcessor> processors) {
        final List<ITextProcessor> unwrapped = new ArrayList<ITextProcessor>(processors.size());
        for (final ITextProcessor processor : processors) {
            unwrapped.add(ProcessorConfigurationUtils.unwrap(processor));
        }
        return unwrapped;
    }


    private static List<ICommentProcessor> unwrapCommentProcessors(final Set<ICommentProcessor> processors) {
        final List<ICommentProcessor> unwrapped = new ArrayList<ICommentProcessor>(processors.size());
        for (final ICommentProcessor processor : processors) {
            unwrapped.add(ProcessorConfigurationUtils.unwrap(processor));
        }
        return unwrapped;
    }



