        final WebEngineContext context = context(new RecordingWebExchange(), variables, "base");

        for (int i = 0; i < 11; i++) {
            context.increaseLevel();
        }
        context.setVariable("a", 11);

        assertEquals(
                "{11:{a=11},0:{a=0}(base)}[11]",
                context.getStringRepresentationByLevel());
    }

    @Test
    void representationIsStableAcrossRepeatedCalls() {
        final Map<String, Object> variables = new LinkedHashMap<>();
        variables.put("a", 1);
        final WebEngineContext context = context(new RecordingWebExchange(), variables, "base");

        context.increaseLevel();
        context.setVariable("a", 2);

        final String first = context.getStringRepresentationByLevel();
        final String second = context.getStringRepresentationByLevel();

        assertEquals(first, second);
        assertEquals("{1:{a=2},0:{a=1}(base)}[1]", first);
    }

    private static WebEngineContext context(
            final IWebExchange exchange, final Map<String, Object> variables, final String templateName) {
        return new WebEngineContext(
                configuration(), templateData(templateName), null, exchange, Locale.ENGLISH, variables);
    }

    private static TemplateData templateData(final String templateName) {
        return new TemplateData(templateName, null, null, null, null);
    }

    private static IEngineConfiguration configuration() {
        return (IEngineConfiguration) Proxy.newProxyInstance(
                IEngineConfiguration.class.getClassLoader(),
                new Class<?>[] { IEngineConfiguration.class },
                (proxy, method, args) -> {
                    final Class<?> returnType = method.getReturnType();
                    if (!returnType.isPrimitive()) {
                        return null;
                    }
                    if (returnType == boolean.class) {
                        return false;
                    }
                    if (returnType == char.class) {
                        return '\0';
                    }
                    if (returnType == byte.class) {
                        return (byte) 0;
                    }
                    if (returnType == short.class) {
                        return (short) 0;
                    }
                    if (returnType == int.class) {
                        return 0;
                    }
                    if (returnType == long.class) {
                        return 0L;
                    }
                    if (returnType == float.class) {
                        return 0.0f;
                    }
                    if (returnType == double.class) {
                        return 0.0d;
                    }
                    return null;
                });
    }

