    @Test
    @DisplayName("A model processor rejects a body already modified by another processor")
    void elementModelProcessorFailsIfBodyWasAlreadyModified() {
        final Fixture fixture = new Fixture(false,
                elementTagProcessor("mytag", 10, (context, tag, handler) -> {
                    final IModel before = context.getModelFactory().createModel();
                    before.add(context.getModelFactory().createText("before"));
                    handler.insertBefore(before);
                }),
                elementModelProcessor("mytag", 20, (context, model, handler) -> {
                    throw new AssertionError("The model processor should not be executed");
                }));

        final TemplateProcessingException exception = assertThrows(
                TemplateProcessingException.class,
                () -> fixture.handler.handleStandaloneElement(fixture.parse("<mytag />")));

        assertTrue(exception.getMessage().contains("Cannot execute model processor"));
        assertTrue(exception.getMessage().contains("already been modified"));
