    @Test
    @DisplayName("Throttled rendering of several standalone elements produces the complete output across chunks")
    void throttledEngineRenderingProducesCompleteOutput() {
        final TemplateEngine templateEngine = new TemplateEngine();
        templateEngine.setDialect(new TestDialect(
                elementTagProcessor("mytag", 10,
                        (context, tag, handler) -> handler.replaceWith("x", false))));
        final IThrottledTemplateProcessor processor =
                templateEngine.processThrottled("<mytag /><mytag /><mytag />", new Context());
        final StringWriter writer = new StringWriter();

        int guard = 0;
        while (!processor.isFinished()) {
            processor.process(1, writer);
            guard++;
            assertTrue(guard < 100, "Throttled processing should finish in a bounded number of chunks");
        }

        assertEquals("xxx", writer.toString());
    }


    private static IProcessor elementTagProcessor(
            final String elementName, final int precedence, final TagAction action) {
        return new AbstractElementTagProcessor(
                TemplateMode.HTML, "tst", elementName, false, null, false, precedence) {
            @Override
            protected void doProcess(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                action.process(context, tag, structureHandler);
            }
        };
    }


    private static IProcessor attributeTagProcessor(
            final String attributeName, final int precedence, final TagAction action) {
        return new AbstractElementTagProcessor(
                TemplateMode.HTML, "tst", null, false, attributeName, false, precedence) {
            @Override
            protected void doProcess(
                    final ITemplateContext context,
                    final IProcessableElementTag tag,
                    final IElementTagStructureHandler structureHandler) {
                action.process(context, tag, structureHandler);
            }
        };
    }


    private static IProcessor textProcessor(final String suffix) {
        return new AbstractTextProcessor(TemplateMode.HTML, 10) {
            @Override
            protected void doProcess(
                    final ITemplateContext context,
                    final IText text,
                    final ITextStructureHandler structureHandler) {
                structureHandler.setText(text.getText() + suffix);
            }
        };
    }


    private static IElementModelProcessor elementModelProcessor(
            final String elementName, final int precedence, final ModelAction action) {
        return new AbstractElementModelProcessor(
                TemplateMode.HTML, "tst", elementName, false, null, false, precedence) {
            @Override
            protected void doProcess(
                    final ITemplateContext context,
                    final IModel model,
                    final IElementModelStructureHandler structureHandler) {
                action.process(context, model, structureHandler);
            }
        };
    }


    private static void assertEvents(final Fixture fixture, final String... expected) {
        final List<String> actual = new ArrayList<String>(fixture.next.events.size());
        for (final ITemplateEvent event : fixture.next.events) {
            actual.add(describe(event));
        }
        assertEquals(Arrays.asList(expected), actual);
    }


    private static String describe(final ITemplateEvent event) {
        if (event instanceof IText) {
            return "text:" + ((IText) event).getText();
        }
        if (event instanceof IStandaloneElementTag) {
            return "standalone:" + ((IStandaloneElementTag) event).getElementCompleteName();
        }
        if (event instanceof IOpenElementTag) {
            return "open:" + ((IOpenElementTag) event).getElementCompleteName();
        }
        if (event instanceof ICloseElementTag) {
            return "close:" + ((ICloseElementTag) event).getElementCompleteName();
        }
        return event.getClass().getSimpleName();
    }


    private interface TagAction {
        void process(ITemplateContext context, IProcessableElementTag tag, IElementTagStructureHandler structureHandler);
    }


    private interface ModelAction {
        void process(ITemplateContext context, IModel model, IElementModelStructureHandler structureHandler);
    }


    private static final class TestDialect extends AbstractDialect implements IProcessorDialect {

        private final Set<IProcessor> processors;

        TestDialect(final IProcessor... processors) {
            super("test-processor-dialect");
            this.processors = new LinkedHashSet<IProcessor>(Arrays.asList(processors));
        }

        public String getPrefix() {
            return "tst";
        }

        public int getDialectProcessorPrecedence() {
            return 0;
        }

        public Set<IProcessor> getProcessors(final String dialectPrefix) {
            return this.processors;
        }
    }


