    }


    @Test
    void throwsWhenNoResolverCanResolveAndFailureIsRequired() {
        this.resolver.resolution = null;

        final TemplateInputException exception = assertThrows(
                TemplateInputException.class,
                () -> this.templateManager.parseStandalone(
                        this.context, TEMPLATE_NAME, null, null, true, true));

