            assertInstanceOf(GenericTokenExpression.class, expression.getTemplateName());
            assertEquals(expectedName, representationOf(expression.getTemplateName()));
            assertNull(expression.getFragmentSelector());
            assertFalse(expression.hasFragmentSelector());
