class StandardExpressionObjectFactoryBuildObjectTests {

    private static final Locale CONTEXT_LOCALE = Locale.CANADA_FRENCH;

    private StandardExpressionObjectFactory factory;
    private IExpressionContext expressionContext;
    private ITemplateContext templateContext;

    @BeforeEach
    void setUp() {
        factory = new StandardExpressionObjectFactory();
        expressionContext = mock(IExpressionContext.class);
        when(expressionContext.getLocale()).thenReturn(CONTEXT_LOCALE);
        templateContext = mock(ITemplateContext.class);
        when(templateContext.getLocale()).thenReturn(CONTEXT_LOCALE);
    }

    @Test
    void returnsContextForContextAliases() {
        assertSame(expressionContext,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.ROOT_EXPRESSION_OBJECT_NAME));
        assertSame(expressionContext,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.VARIABLES_EXPRESSION_OBJECT_NAME));
        assertSame(expressionContext,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.CONTEXT_EXPRESSION_OBJECT_NAME));
    }

    @Test
    void returnsLocaleForLocaleAlias() {
        assertSame(CONTEXT_LOCALE,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.LOCALE_EXPRESSION_OBJECT_NAME));
    }

    @Test
    void returnsSelectionTargetForTemplateContextWithSelectionTarget() {
        final Object selectionTarget = new Object();
        when(templateContext.hasSelectionTarget()).thenReturn(true);
        when(templateContext.getSelectionTarget()).thenReturn(selectionTarget);

        assertSame(selectionTarget,
                factory.buildObject(templateContext, StandardExpressionObjectFactory.SELECTION_TARGET_EXPRESSION_OBJECT_NAME));
    }

    @Test
    void returnsTemplateContextForSelectionTargetWhenNoSelectionTargetExists() {
        when(templateContext.hasSelectionTarget()).thenReturn(false);

        assertSame(templateContext,
                factory.buildObject(templateContext, StandardExpressionObjectFactory.SELECTION_TARGET_EXPRESSION_OBJECT_NAME));
        verify(templateContext, never()).getSelectionTarget();
    }

    @Test
    void returnsNonTemplateContextForSelectionTarget() {
        assertSame(expressionContext,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.SELECTION_TARGET_EXPRESSION_OBJECT_NAME));
    }

    @Test
    void rejectsLegacyServletExpressionObjectNames() {
        final String expectedMessage =
                "The 'request','session','servletContext' and 'response' expression utility objects are no " +
                "longer available by default for template expressions and their use is not recommended. In " +
                "cases where they are really needed, they should be manually added as context variables.";

        final String[] legacyNames = {
                StandardExpressionObjectFactory.REQUEST_EXPRESSION_OBJECT_NAME,
                StandardExpressionObjectFactory.SESSION_EXPRESSION_OBJECT_NAME,
                StandardExpressionObjectFactory.SERVLET_CONTEXT_EXPRESSION_OBJECT_NAME,
                StandardExpressionObjectFactory.RESPONSE_EXPRESSION_OBJECT_NAME
        };

        for (final String legacyName : legacyNames) {
            final IllegalArgumentException exception = assertThrows(
                    IllegalArgumentException.class,
                    () -> factory.buildObject(expressionContext, legacyName));
            assertEquals(expectedMessage, exception.getMessage());
        }
    }

    @Test
    void buildsContextBasedExpressionUtilityObjects() {
        assertInstanceOf(Conversions.class,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.CONVERSIONS_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(Calendars.class,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.CALENDARS_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(Temporals.class,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.TEMPORALS_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(Dates.class,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.DATES_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(Numbers.class,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.NUMBERS_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(Strings.class,
                factory.buildObject(expressionContext, StandardExpressionObjectFactory.STRINGS_EXPRESSION_OBJECT_NAME));
    }

    @Test
    void returnsSharedStatelessExpressionUtilityObjects() {
        assertSharedExpressionObject(Uris.class, StandardExpressionObjectFactory.URIS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Bools.class, StandardExpressionObjectFactory.BOOLS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Objects.class, StandardExpressionObjectFactory.OBJECTS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Arrays.class, StandardExpressionObjectFactory.ARRAYS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Lists.class, StandardExpressionObjectFactory.LISTS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Sets.class, StandardExpressionObjectFactory.SETS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Maps.class, StandardExpressionObjectFactory.MAPS_EXPRESSION_OBJECT_NAME);
        assertSharedExpressionObject(Aggregates.class, StandardExpressionObjectFactory.AGGREGATES_EXPRESSION_OBJECT_NAME);
    }

    @Test
    void buildsTemplateOnlyExpressionUtilityObjectsForTemplateContext() {
        assertInstanceOf(Messages.class,
                factory.buildObject(templateContext, StandardExpressionObjectFactory.MESSAGES_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(Ids.class,
                factory.buildObject(templateContext, StandardExpressionObjectFactory.IDS_EXPRESSION_OBJECT_NAME));
        assertInstanceOf(ExecutionInfo.class,
                factory.buildObject(templateContext, StandardExpressionObjectFactory.EXECUTION_INFO_OBJECT_NAME));
    }

    @Test
    void returnsNullForTemplateOnlyExpressionUtilityObjectsWithNonTemplateContext() {
        assertNull(factory.buildObject(expressionContext,
                StandardExpressionObjectFactory.MESSAGES_EXPRESSION_OBJECT_NAME));
        assertNull(factory.buildObject(expressionContext,
                StandardExpressionObjectFactory.IDS_EXPRESSION_OBJECT_NAME));
        assertNull(factory.buildObject(expressionContext,
                StandardExpressionObjectFactory.EXECUTION_INFO_OBJECT_NAME));
    }

    @Test
    void returnsNullForUnknownAndNullExpressionObjectNames() {
        assertNull(factory.buildObject(expressionContext, "notAnExpressionObject"));
        assertNull(factory.buildObject(expressionContext, null));
    }

    private <T> void assertSharedExpressionObject(final Class<T> expectedType, final String expressionObjectName) {
        final Object first = factory.buildObject(templateContext, expressionObjectName);
        final Object second = factory.buildObject(templateContext, expressionObjectName);

        assertInstanceOf(expectedType, first);
        assertSame(first, second);
    }

}

