            this.events.add("closeEnd[" + line + "," + col + "]:" + new String(buffer, nameOffset, nameLen));
        }

        @Override
        public void handleAttribute(
                final char[] buffer,
                final int nameOffset, final int nameLen, final int nameLine, final int nameCol,
                final int operatorOffset, final int operatorLen, final int operatorLine, final int operatorCol,
                final int valueContentOffset, final int valueContentLen,
                final int valueOuterOffset, final int valueOuterLen, final int valueLine, final int valueCol) {
            this.events.add("attribute[" + nameLine + "," + nameCol + "]:"
                    + new String(buffer, nameOffset, nameLen)
                    + new String(buffer, operatorOffset, operatorLen)
                    + escape(new String(buffer, valueOuterOffset, valueOuterLen)));
        }

        private static String escape(final String text) {
            return text.replace("\n", "\\n");
        }

    }


    /**
     * A reader that returns at most {@code chunkSize} characters per {@code read} call, so that the
     * multiple-reads / buffer-shifting logic of the parser can be exercised deterministically.
     */
    static final class ChunkReader extends Reader {

        private final String content;
        private final int chunkSize;
        private final int failAfterChars;
        private final boolean failOnClose;

        private int pos = 0;
        boolean closed = false;

        ChunkReader(final String content, final int chunkSize) {
            this(content, chunkSize, Integer.MAX_VALUE, false);
        }

        ChunkReader(final String content, final int chunkSize, final int failAfterChars, final boolean failOnClose) {
            this.content = content;
            this.chunkSize = chunkSize;
            this.failAfterChars = failAfterChars;
            this.failOnClose = failOnClose;
        }

        @Override
        public int read(final char[] cbuf, final int off, final int len) throws IOException {
            if (this.pos >= this.failAfterChars) {
                throw new IOException("Simulated read failure at position " + this.pos);
            }
            if (this.pos >= this.content.length()) {
                return -1;
            }
            final int n = Math.min(Math.min(this.chunkSize, len), this.content.length() - this.pos);
            this.content.getChars(this.pos, this.pos + n, cbuf, off);
            this.pos += n;
            return n;
        }

        @Override
        public void close() throws IOException {
            this.closed = true;
            if (this.failOnClose) {
                throw new IOException("Simulated close failure");
            }
        }

    }


    private static TextParser parser(
            final int poolSize, final int poolBufferSize,
            final boolean processCommentsAndLiterals, final boolean standardDialectPresent) {
        return new TextParser(poolSize, poolBufferSize, processCommentsAndLiterals, standardDialectPresent);
    }


    private static RecordingHandler parse(
            final TextParser textParser, final Reader reader, final int suggestedBufferSize)
            throws TextParseException {
        final RecordingHandler handler = new RecordingHandler();
        textParser.parseDocument(reader, suggestedBufferSize, handler);
        return handler;
    }


    private static RecordingHandler parseDocument(
            final String document, final int bufferSize, final int chunkSize,
            final boolean processCommentsAndLiterals) throws TextParseException {
        final Reader reader = (chunkSize > 0 ?
                new ChunkReader(document, chunkSize) : new StringReader(document));
        return parse(parser(3, bufferSize, processCommentsAndLiterals, true), reader, bufferSize);
    }


