    @Test
    public void testEventStreamDoesNotDependOnBufferSizeNorReadChunking() throws Exception {

        final String[] documents = new String[] {
                "[#elem attr1=\"value1\" attr2='value2']text[/elem]",
                "[#elem]line1\nline2[/elem]tail",
                "preamble /* c1 */ middle /* c2 */ end",
                "x \"lit\nwith\nnewlines\" y [#a]z[/a]",
                "1234567890123456789012345678901234567890",
                "a\nb\nc\nd\ne\nf\ng\nh\ni\nj",
                "[#a][#b][#c]t[/c][/b][/a]",
                "[#elem /]text[#elem2/]"
        };

        for (final String document : documents) {

            final RecordingHandler reference = parseDocument(document, 128, 0, true);

            assertFalse(reference.events.isEmpty());
            assertEquals("documentStart[1,1]", reference.events.get(0));
            assertTrue(reference.events.get(reference.events.size() - 1).startsWith("documentEnd["));

            for (final int bufferSize : new int[] {6, 7, 9, 13, 100}) {
                for (final int chunkSize : new int[] {1, 2, 5, 40}) {
                    final RecordingHandler actual = parseDocument(document, bufferSize, chunkSize, true);
                    assertEquals(
                            reference.events, actual.events,
                            "Different events for document \"" + document + "\" with bufferSize=" + bufferSize
                                    + " and chunkSize=" + chunkSize);
                    assertEquals(reference.endLine, actual.endLine);
                    assertEquals(reference.endCol, actual.endCol);
                }
            }

        }

    }


