package org.thymeleaf.util;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;


/**
 * Tests for {@link AggregateCharSequence#equals(Object)}.
 */
public final class AggregateCharSequenceEqualsTests {


    private static AggregateCharSequence agg(final CharSequence... components) {
        return new AggregateCharSequence(components);
    }

    private static AggregateCharSequence aggList(final CharSequence... components) {
        final List<CharSequence> list = new ArrayList<CharSequence>(Arrays.asList(components));
        return new AggregateCharSequence(list);
    }


    // ----------------------------------------------------------------------
    // Reference equality and non-AggregateCharSequence arguments
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns true for the very same instance")
    public void testSameInstanceIsEqual() {
        final AggregateCharSequence a = agg("abc", "def");
        assertTrue(a.equals(a));
        // Same instance, even after the hash value has been cached
        assertTrue(a.hashCode() != 0 || a.length() == 0);
        assertTrue(a.equals(a));
    }

    @Test
    @DisplayName("equals() returns true for the same empty instance")
    public void testSameEmptyInstanceIsEqual() {
        final AggregateCharSequence a = agg();
        assertTrue(a.equals(a));
        assertEquals(0, a.length());
    }

    @Test
    @DisplayName("equals() returns false for null")
    public void testNullIsNotEqual() {
        final AggregateCharSequence a = agg("abc");
        assertFalse(a.equals(null));
        assertFalse(agg().equals(null));
    }

    @Test
    @DisplayName("equals() returns false for unrelated types")
    public void testOtherTypesAreNotEqual() {
        final AggregateCharSequence a = agg("abc", "def");

        assertFalse(a.equals("abcdef"));
        assertFalse(a.equals(new StringBuilder("abcdef")));
        assertFalse(a.equals(new StringBuffer("abcdef")));
        assertFalse(a.equals(Integer.valueOf(0)));
        assertFalse(a.equals(new Object()));

        final AggregateCharSequence empty = agg();
        assertFalse(empty.equals(""));
        assertFalse(empty.equals(new StringBuilder()));
    }


    // ----------------------------------------------------------------------
    // Single-component String fast path
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns true for two single-String sequences with equal text")
    public void testSingleStringEqual() {
        assertTrue(agg("abc").equals(agg("abc")));
        assertTrue(agg("").equals(agg("")));
        assertTrue(agg("a").equals(agg("a")));
    }

    @Test
    @DisplayName("equals() returns false for two single-String sequences with different text")
    public void testSingleStringDifferentSameLength() {
        assertFalse(agg("abc").equals(agg("abd")));
        assertFalse(agg("a").equals(agg("b")));
        assertFalse(agg("Abc").equals(agg("abc")));
    }

    @Test
    @DisplayName("equals() returns false for two single-String sequences of different length")
    public void testSingleStringDifferentLength() {
        assertFalse(agg("abc").equals(agg("ab")));
        assertFalse(agg("").equals(agg("a")));
        assertFalse(agg("a").equals(agg("")));
    }


    // ----------------------------------------------------------------------
    // Length handling and empty sequences
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns false when the aggregated lengths differ")
    public void testDifferentLengthsAreNotEqual() {
        assertFalse(agg("abc", "def").equals(agg("abc", "de")));
        assertFalse(agg("abc", "de").equals(agg("abc", "def")));
        assertFalse(agg("abc", "def").equals(agg("abcdefg")));
        assertFalse(agg("abcdef").equals(agg("abc", "def", "g")));
    }

    @Test
    @DisplayName("equals() returns true for all the representations of the empty sequence")
    public void testEmptySequencesAreEqual() {
        final AggregateCharSequence fromEmptyArray = agg();
        final AggregateCharSequence fromEmptyList = new AggregateCharSequence(Collections.<CharSequence>emptyList());
        final AggregateCharSequence fromEmptyString = agg("");
        final AggregateCharSequence fromTwoEmptyStrings = agg("", "");
        final AggregateCharSequence fromThreeEmptyStrings = agg("", "", "");

        final AggregateCharSequence[] all =
                new AggregateCharSequence[] {
                        fromEmptyArray, fromEmptyList, fromEmptyString,
                        fromTwoEmptyStrings, fromThreeEmptyStrings};

        for (int i = 0; i < all.length; i++) {
            for (int j = 0; j < all.length; j++) {
                assertEquals(0, all[i].length());
                assertTrue(all[i].equals(all[j]),
                        "Empty sequences at positions " + i + " and " + j + " should be equal");
            }
        }
    }

    @Test
    @DisplayName("equals() returns false between the empty sequence and any non-empty one")
    public void testEmptyAndNonEmpty() {
        assertFalse(agg().equals(agg("a")));
        assertFalse(agg("a").equals(agg()));
        assertFalse(agg("", "").equals(agg("a", "")));
        assertFalse(agg("", "", "a").equals(agg("", "")));
    }


    // ----------------------------------------------------------------------
    // Content equality across different component partitions
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns true when the same text is split differently")
    public void testDifferentPartitionsOfSameText() {
        assertTrue(agg("abc", "def").equals(agg("ab", "cdef")));
        assertTrue(agg("abc", "def").equals(agg("a", "b", "c", "d", "e", "f")));
        assertTrue(agg("abcdef").equals(agg("abc", "def")));
        assertTrue(agg("a", "b", "c").equals(agg("ab", "c")));
        assertTrue(agg("aab", "b").equals(agg("aa", "bb")));
        assertTrue(agg("abcd", "efgh", "ijkl").equals(agg("abcde", "fghijkl")));
        assertTrue(agg("abc", "def").equals(agg("abcd", "ef")));
        assertTrue(agg("abcd", "ef").equals(agg("abc", "def")));
    }

    @Test
    @DisplayName("equals() returns true when the text is split around empty components")
    public void testEmptyComponentsAreSkipped() {
        assertTrue(agg("", "abc", "").equals(agg("abc")));
        assertTrue(agg("abc").equals(agg("", "abc", "")));
        assertTrue(agg("a", "", "bc").equals(agg("ab", "c")));
        assertTrue(agg("ab", "", "cd").equals(agg("ab", "c", "d")));
        assertTrue(agg("", "ab", "", "cd", "").equals(agg("a", "bcd", "")));
        assertTrue(agg("", "", "abcdef", "", "").equals(agg("abc", "def")));
    }

    @Test
    @DisplayName("equals() returns true for a single component of the same text built with a List")
    public void testListBasedConstruction() {
        assertTrue(aggList("abc", "def").equals(agg("abcdef")));
        assertTrue(agg("abcdef").equals(aggList("abc", "def")));
        assertTrue(aggList("abc", "def").equals(aggList("ab", "cde", "f")));
        assertFalse(aggList("abc", "def").equals(aggList("abc", "dee")));
    }


    // ----------------------------------------------------------------------
    // Mismatching content
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns false when the first component differs")
    public void testMismatchInFirstComponent() {
        assertFalse(agg("abc", "def").equals(agg("abd", "def")));
        assertFalse(agg("abc", "def").equals(agg("xbc", "def")));
        assertFalse(agg("abcdef").equals(agg("abcdef".substring(0, 5) + "X")));
    }

    @Test
    @DisplayName("equals() returns false when the last component differs")
    public void testMismatchInLastComponent() {
        assertFalse(agg("abc", "def").equals(agg("abc", "deg")));
        assertFalse(agg("abc", "def").equals(agg("abc", "de")));
        assertFalse(agg("abc", "def", "ghi").equals(agg("abc", "def", "ghj")));
    }

    @Test
    @DisplayName("equals() returns false when the mismatch happens at a component boundary")
    public void testMismatchAtBoundary() {
        assertFalse(agg("ab", "cd").equals(agg("ab", "ce")));
        assertFalse(agg("ab", "cd").equals(agg("aa", "cd")));
        assertFalse(agg("aab", "b").equals(agg("aa", "bc")));
        assertFalse(agg("abcd", "ef").equals(agg("abc", "dgf")));
    }

    @Test
    @DisplayName("equals() returns false when only the last character differs")
    public void testMismatchInLastCharacter() {
        assertFalse(agg("abc", "de").equals(agg("abc", "df")));
        assertFalse(agg("a", "b", "c").equals(agg("a", "b", "d")));
        assertFalse(agg("a", "bc", "").equals(agg("a", "bd", "")));
    }


    // ----------------------------------------------------------------------
    // Non-String CharSequence components
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() compares non-String components character by character")
    public void testNonStringComponents() {
        assertTrue(agg(new StringBuilder("abc")).equals(agg("abc")));
        assertTrue(agg("abc").equals(agg(new StringBuilder("abc"))));
        assertTrue(agg(new StringBuilder("abc"), new StringBuilder("def")).equals(agg("abcdef")));
        assertTrue(agg("abcdef").equals(agg(new StringBuilder("abc"), new StringBuilder("def"))));
        assertTrue(agg(new StringBuffer("abc"), "def").equals(agg("abc", new StringBuilder("def"))));

        assertFalse(agg(new StringBuilder("abc")).equals(agg("abd")));
        assertFalse(agg(new StringBuilder("abc"), "def").equals(agg("abc", "deg")));
        assertFalse(agg("abc").equals(agg(new StringBuilder("abd"))));
    }

    @Test
    @DisplayName("equals() works with a custom CharSequence implementation")
    public void testCustomCharSequenceComponent() {
        assertTrue(agg(new PlainCharSequence("abc"), "def").equals(agg("abcdef")));
        assertTrue(agg("abcdef").equals(agg(new PlainCharSequence("abc"), "def")));
        assertFalse(agg(new PlainCharSequence("abc"), "def").equals(agg("abcdeg")));
    }


    // ----------------------------------------------------------------------
    // Hash-code interaction (cached hash shortcut)
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() returns false for cached-hash sequences with different content")
    public void testCachedHashShortcutDifferentContent() {
        final AggregateCharSequence a = agg("abc", "def");
        final AggregateCharSequence b = agg("xbc", "def");

        // Force the hash value to be computed and cached in both objects
        final int hashA = a.hashCode();
        final int hashB = b.hashCode();

        assertNotEquals(hashA, hashB);
        assertFalse(a.equals(b));
        assertFalse(b.equals(a));
    }

    @Test
    @DisplayName("equals() returns true for cached-hash sequences with equal content")
    public void testCachedHashShortcutEqualContent() {
        final AggregateCharSequence a = agg("ab", "cdef");
        final AggregateCharSequence b = agg("abc", "def");
        final AggregateCharSequence c = agg("abcdef");

        assertEquals(a.hashCode(), b.hashCode());
        assertEquals(b.hashCode(), c.hashCode());

        assertTrue(a.equals(b));
        assertTrue(b.equals(a));
        assertTrue(a.equals(c));
        assertTrue(c.equals(a));
    }

    @Test
    @DisplayName("equals() returns true for cached-hash empty sequences")
    public void testCachedHashEmptySequences() {
        final AggregateCharSequence a = agg("");
        final AggregateCharSequence b = agg("", "");

        assertEquals(0, a.hashCode());
        assertEquals(0, b.hashCode());
        assertTrue(a.equals(b));
        assertTrue(b.equals(a));
    }


    // ----------------------------------------------------------------------
    // General contract: symmetry, reflexivity and hashCode consistency
    // ----------------------------------------------------------------------

    @Test
    @DisplayName("equals() is symmetric for equal and non-equal sequences")
    public void testSymmetry() {
        final AggregateCharSequence[] sequences = new AggregateCharSequence[] {
                agg(),
                agg(""),
                agg("a"),
                agg("abc"),
                agg("abc", "def"),
                agg("abcdef"),
                agg("ab", "cdef"),
                agg("", "abc", ""),
                agg("abd", "def"),
                agg("abc", "de"),
                agg(new StringBuilder("abc"), "def")
        };

        for (int i = 0; i < sequences.length; i++) {
            for (int j = 0; j < sequences.length; j++) {
                final boolean forward = sequences[i].equals(sequences[j]);
                final boolean backward = sequences[j].equals(sequences[i]);
                assertEquals(forward, backward,
                        "equals() must be symmetric for indices " + i + " and " + j);
                if (forward) {
                    assertEquals(sequences[i].length(), sequences[j].length());
                    assertEquals(sequences[i].hashCode(), sequences[j].hashCode(),
                            "Equal sequences must have equal hash codes (indices " + i + " and " + j + ")");
                }
            }
        }
    }

    @Test
    @DisplayName("equals() is reflexive for every sequence")
    public void testReflexivity() {
        final AggregateCharSequence[] sequences = new AggregateCharSequence[] {
                agg(),
                agg(""),
                agg("abc"),
                agg("abc", "def"),
                agg(new StringBuilder("abc"), "def", new StringBuilder("ghi"))
        };

        for (final AggregateCharSequence sequence : sequences) {
            assertTrue(sequence.equals(sequence));
            // Reflexivity also holds after the hash has been cached
            sequence.hashCode();
            assertTrue(sequence.equals(sequence));
        }
    }

    @Test
    @DisplayName("equals() is transitive for equal sequences with different partitions")
    public void testTransitivity() {
        final AggregateCharSequence a = agg("abc", "def");
        final AggregateCharSequence b = agg("ab", "cd", "ef");
        final AggregateCharSequence c = agg("a", "b", "c", "d", "e", "f");

        assertTrue(a.equals(b));
        assertTrue(b.equals(c));
        assertTrue(a.equals(c));
        assertTrue(c.equals(a));
    }

    @Test
    @DisplayName("equals() handles a large number of components")
    public void testManyComponents() {

        final StringBuilder expected = new StringBuilder();
        final CharSequence[] components = new CharSequence[100];
        for (int i = 0; i < components.length; i++) {
            components[i] = String.valueOf((char) ('a' + (i % 26)));
            expected.append(components[i]);
        }
        final AggregateCharSequence a = new AggregateCharSequence(components);

        assertTrue(a.equals(agg(expected.toString())));
        assertTrue(agg(expected.toString()).equals(a));

        final CharSequence[] differentComponents = components.clone();
        differentComponents[99] = "Z";
        final AggregateCharSequence b = new AggregateCharSequence(differentComponents);
        assertEquals(a.length(), b.length());
        assertFalse(a.equals(b));
        assertFalse(b.equals(a));
    }

    @Test
    @DisplayName("equals() compares correctly when only one of the sequences has a cached hash")
    public void testOnlyOneCachedHash() {

        final AggregateCharSequence a = agg("ab", "cd");
        assertNotEquals(0, a.hashCode());

        final AggregateCharSequence b = agg("abcd");
        assertTrue(a.equals(b));
        assertTrue(b.equals(a));

        final AggregateCharSequence c = agg("abce");
        assertFalse(a.equals(c));
        assertFalse(c.equals(a));
    }

    @Test
    @DisplayName("equals() ignores a trailing empty component")
    public void testTrailingEmptyComponent() {
        assertTrue(agg("abc", "").equals(agg("ab", "c")));
        assertTrue(agg("ab", "c").equals(agg("abc", "")));
        assertTrue(agg("a", "bc", "").equals(agg("abc")));
        assertFalse(agg("abc", "").equals(agg("abd")));
    }


    private static final class PlainCharSequence implements CharSequence {

        private final String text;

        PlainCharSequence(final String text) {
            super();
            this.text = text;
        }

        public int length() {
            return this.text.length();
        }

        public char charAt(final int index) {
            return this.text.charAt(index);
        }

        public CharSequence subSequence(final int start, final int end) {
            return new PlainCharSequence(this.text.substring(start, end));
        }

        @Override
        public String toString() {
            return this.text;
        }

    }

}

