                VersionUtils.parseVersion("1.2.3-beta2", null),
                1, 2, 3, "beta2", "1.2.3", "1.2.3-beta2", null);
    }

    @Test
    public void testQualifierWithCustomSeparator() {
        assertKnownVersion(
                VersionUtils.parseVersion("1.2.3+build", null),
                1, 2, 3, "build", "1.2.3", "1.2.3+build", null);
    }

    @Test
    public void testQualifierWithUnderscoreSeparator() {
