    @Test
    public void testLowerCaseReleaseQualifierIsNotStable() {
        final VersionSpec spec = assertKnownVersion(
                VersionUtils.parseVersion("1.2.3.release", null),
                1, 2, 3, "release", "1.2.3", "1.2.3.release", null);
        assertFalse(spec.isStableRelease(), "Lower-case 'release' is not the stable qualifier");
    }

    @Test
