    @Test
    public void testKnownVersionWithBuildTimestamp() {
        final VersionSpec spec = assertKnownVersion(
                VersionUtils.parseVersion("1.2.3", BUILD_TIMESTAMP),
                1, 2, 3, null, "1.2.3", "1.2.3", BUILD_TIMESTAMP);
        assertEquals("1.2.3 (" + BUILD_TIMESTAMP + ")", spec.getFullVersion());
    }

    @Test
